<template>
  <div class="saved-filter-badge row absolute">
    <template v-for="[key, value] in quickFilterMap" :key="key">
      <template v-if="key == 'status' || key == 'paid_status'">
        <q-badge rounded color="primary" class="q-mr-sm capitalize">
          <template v-slot>
            {{ $t(value.value) }}
            <q-icon
              name="close"
              color="white"
              size="xs"
              class="q-ml-xs font-12 cursor-pointer"
              @click="removeFilter(key)"
            />
          </template>
        </q-badge>
      </template>
      <q-badge rounded color="primary" class="q-mr-sm capitalize" v-else>
        {{ value }}
        <q-icon
          name="close"
          color="white"
          class="q-ml-xs font-12 cursor-pointer"
          size="xs"
          @click="removeFilter(key)"
        />
      </q-badge>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { invoiceDashboardStore } from 'src/store/main';

export default defineComponent({
  mounted() {
    this.init();
  },
  methods: {
    async init() {
      await this.$nextTick();
    },

    removeFilter(key: string) {
      this.quickFilterMap.delete(key);
      if (key in this.params) {
        this.params[key as keyof typeof this.params] = '';
      }
      this.getDataServer();
    },
    async getDataServer() {
      try {
        this.loading = true;
        await this.getInvoiceData();
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    const invoice_store = invoiceDashboardStore();
    const { loading, params, quickFilterMap } = storeToRefs(invoice_store);
    const { getInvoiceData } = invoice_store;

    return {
      loading,
      params,
      quickFilterMap,
      getInvoiceData,
    };
  },
});
</script>

<style lang="css" scoped>
.font-12 {
  font-size: 12px !important;
}
</style>
