<template>
  <q-input
    outlined
    dense
    :clearable="true"
    :debounce="1000"
    class="q-mr-sm"
    style="width: 227px; height: 40px"
    v-model="params.supplier_name"
    @update:model-value="fetchData"
  >
  </q-input>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { invoiceDashboardStore } from 'src/store/main';

export default defineComponent({
  mixins: [],
  props: {},
  watch: {
    'params.supplier_name': {
      deep: true,
      handler: function (newVal, oldVal) {
        this.handleQuikFilter();
      },
    },
  },
  methods: {
    fetchData() {
      this.params.supplier_name
        ? this.quickFilterMap.set('supplier_name', this.params.supplier_name)
        : this.quickFilterMap.delete('supplier_name');
      this.resetPagination();
      this.getInvoiceData();
    },
    handleQuikFilter() {
      if (
        !this.params.supplier_name ||
        this.params.supplier_name.trim() === ''
      ) {
        this.quickFilterMap.delete('supplier_name');
      } else {
        this.quickFilterMap.set('supplier_name', this.params.supplier_name);
      }
    },
  },
  setup() {
    const invoice_store = invoiceDashboardStore();
    const { params, quickFilterMap } = storeToRefs(invoice_store);

    const { getInvoiceData, resetPagination } = invoice_store;

    return {
      params,
      getInvoiceData,
      resetPagination,
      quickFilterMap,
    };
  },
});
</script>

