<template>
  <div class="row q-mb-md">
    <div
      style="margin-top: 39px"
      class="row items-start example-container dashboard-title dark-readable"
    >
      <div
        class="example-cell cursor-pointer"
        tabindex="0"
        @click="getAllInvoices"
      >
        {{ $t('all') }} ({{ total_count || 0 }})
      </div>
      <div
        class="example-cell q-ml-lg cursor-pointer"
        tabindex="0"
        @click="getInvoiceStatus('Invoiced')"
      >
        {{ $t('invoiced') }} ({{ total_invoice_count }})
      </div>
      <div
        class="example-cell q-ml-lg cursor-pointer"
        tabindex="0"
        @click="getInvoiceStatus('Closed')"
      >
        {{ $t('closed') }} ({{ total_closed_count }})
      </div>
    </div>

    <div class="col q-ml-xl">
      <div class="row justify-start">
        <div class="dashboard-search-box q-ml-md mt-20 white-inputs">
          <quickSearch />
        </div>
        <q-space />
        <f-btn
          square
          class="q-mr-sm mt-20"
          @click="refreshFilters"
        >
          <Icon icon="mdi:refresh" width="20" height="20" />
          <q-tooltip>{{ $t('refresh_list') }}</q-tooltip>
        </f-btn>
        <f-btn
          square
          class="mt-20"
          @click="openColumnSettings"
        >
          <Icon icon="mdi:filter-variant" width="20" height="20" />
          <q-tooltip>{{ $t('table_column_settings_tooltip') }}</q-tooltip>
        </f-btn>
        <ColumnSettings
          ref="columnSettingsRef"
          :columns="allColumns"
          :visible-column-objects="visibleColumns"
          :show-trigger-button="false"
          label-key="translation_key"
          :enable-batch-selection="true"
          @open="onColumnSettingsOpen"
          @save="onColumnSettingsSave"
          @cancel="onColumnSettingsCancel"
        />
      </div>
    </div>
  </div>

  <div
    class="row mb-25 relative-position"
    style="margin-bottom: 8px"
    v-if="quickFilterMap.size > 0"
  >
    <div class="dashboard-toggler-area"></div>
    <savedFilterBadges />
  </div>
</template>

<script lang="ts">

import { ref, defineComponent } from 'vue';
import quickSearch from './filter/quick-search.vue';
import { invoiceDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { ColumnSettings } from 'src/components/Table';
import type { ColumnSettingsSavePayload, ColumnSettingsExposed } from 'src/components/Table';
import savedFilterBadges from 'src/pages/Invoice/components/filter/saved-filter-badges.vue';

export default defineComponent({
  name: 'InvoiceHeader',
  components: {
    
    quickSearch,
    ColumnSettings,
    savedFilterBadges,
  },
  setup() {
    const invoiceStore = invoiceDashboardStore();

    const {
      total_count,
      total_invoice_count,
      total_closed_count,
      params,
      table_columns,
      quickFilterMap,
    } = storeToRefs(invoiceStore);

    const { getInvoiceData, resetFilter, resetPagination, getSavedColumns, saveColumnOrder } = invoiceStore;

    return {
      // Store refs
      total_count,
      total_invoice_count,
      total_closed_count,
      params,
      table_columns,
      quickFilterMap,
      // Store methods
      getInvoiceData,
      resetFilter,
      resetPagination,
      getSavedColumns,
      saveColumnOrder,
      // Component refs
      columnSettingsRef: ref<ColumnSettingsExposed | null>(null),
      // State
      visibleColumns: ref<Record<string, any>>({}),
    };
  },
  computed: {
    /**
     * All available columns mapped to ColumnSettings format
     */
    allColumns(): any[] {
      return Object.values(this.table_columns).map((col: any) => ({
        name: col.name,
        label: col.translation_key,
        translation_key: col.translation_key,
        field: col.field,
        actions: col.actions,
        order: col.order,
        visible: true,
      }));
    },
  },
  async mounted() {
    try {
      const savedColumns = await this.getSavedColumns();
      this.visibleColumns = savedColumns && Object.keys(savedColumns).length > 0
        ? savedColumns
        : { ...this.table_columns };
    } catch {
      this.visibleColumns = { ...this.table_columns };
    }
  },
  methods: {
    /**
     * Load saved column settings when dialog opens
     */
    async onColumnSettingsOpen() {
      try {
        const savedColumns = await this.getSavedColumns();
        if (savedColumns && Object.keys(savedColumns).length > 0) {
          this.visibleColumns = savedColumns;
        } else {
          this.visibleColumns = { ...this.table_columns };
        }
      } catch (err) {
        logError('Failed to load saved columns:', err);
        this.visibleColumns = { ...this.table_columns };
      }
    },
    /**
     * Save column settings when user clicks Done
     */
    async onColumnSettingsSave(payload: ColumnSettingsSavePayload) {
      try {
        // Map to the format expected by saveColumnOrder
        const columnsToSave = payload.visibleColumns.map((col, index) => ({
          name: col.name,
          translation_key: col.translation_key || col.label,
          field: col.name,
          actions: col.actions ?? true,
          order: index,
        }));

        await this.saveColumnOrder(columnsToSave);

        // Close the dialog
        this.columnSettingsRef?.close();

        // Dispatch event to notify table of column changes
        const event = new CustomEvent('columnsUpdated', {
          detail: {
            visible_columns: columnsToSave.reduce((acc: any, col) => {
              acc[col.name] = col;
              return acc;
            }, {}),
          },
        });
        document.dispatchEvent(event);

        // Also dispatch reload_columns for backwards compatibility
        document.dispatchEvent(new CustomEvent('reload_columns', {}));
      } catch (err) {
        logError('Failed to save column settings:', err);
        this.columnSettingsRef?.setSaving(false);
      }
    },
    /**
     * Handle cancel - just close the dialog
     */
    onColumnSettingsCancel() {
      // Nothing special needed, dialog handles closing
    },
    /**
     * Open the column settings dialog
     */
    openColumnSettings() {
      this.columnSettingsRef?.open();
    },
    /**
     * Refresh filters and reload data
     */
    refreshFilters() {
      this.getInvoiceData();
    },
    /**
     * Get all invoices (clear filters)
     */
    getAllInvoices() {
      this.quickFilterMap.clear();
      this.resetFilter();
      this.getInvoiceData();
    },
    /**
     * Filter by invoice status
     */
    async getInvoiceStatus(status: string) {
      const stt = { label: status, value: status };
      this.params.status = stt as any;
      this.quickFilterMap.set('status', this.params.status);
      this.resetPagination();
      await this.getInvoiceData();
    },
  },
});
</script>
