<template>
  <q-select
    outlined
    class="q-mr-sm"
    style="width: 227px; height: 40px"
    clearable
    dense
    v-model="params.status"
    :options="statusOptions"
    :label="$t('status')"
    @update:model-value="fetchData"
  >
    <template v-slot:selected-item="scope">
      <div>{{ scope.opt.label }}</div>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { invoiceDashboardStore } from 'src/store/main';

export default defineComponent({
  methods: {
    fetchData() {
      this.params.status
        ? this.quickFilterMap.set('status', this.params.status)
        : this.quickFilterMap.delete('status');
      this.resetPagination();
      this.getInvoiceData();
    },
  },
  setup() {
    const invoice_store = invoiceDashboardStore();
    const { params, quickFilterMap } = storeToRefs(invoice_store);

    const { getInvoiceData, resetPagination } = invoice_store;

    return {
      params,
      quickFilterMap,
      resetPagination,
      getInvoiceData,
      statusOptions: [
        { label: 'Open', value: 'Open' },
        { label: 'Paid', value: 'Paid' },
        { label: 'Invoiced', value: 'Invoiced' },
        { label: 'Closed', value: 'Closed' },
      ],
    };
  },
});
</script>

<style lang="scss">
.select-box.doc-type-select {
  max-width: 260px;
}
</style>
