<template>
<MessageBanner v-if="invoiceDashboardDisabled" :dissmiss_btn="false" :back_route="false" :message="$t('ACTION_NOT_ALLOWED')" />
<template v-else>
  <SubHeader name="invoice_dashboard" :label="$t('invoice_dashboard')"> </SubHeader>

  <div class="dashboard-container dashboard-text-color dashboard-main">
    <InvoiceDashboardHeader />

    <q-separator class="seperator" />
    <div class="full-width dashboard-list-area q-my-lg" style="overflow-x: auto;">
      <DocBitsTable
        :rows="tableRows"
        :columns="v2TableColumns"
        row-key="id"
        table-id="invoice_table"
        :loading="loading"
        :features="v2TableFeatures"
        :row-actions="v2RowActions"
        :pagination="v2PaginationState"
        :rows-per-page-options="[10, 20, 25, 50]"
        pagination-label="pagination_size"
        :pagination-settings-key="pagination_settings_key"
        no-data-label="NO_RECORD_FOUND"
        :column-order="v2ColumnOrder"
        table-class="scroll-height-100vh-265px"
        @update:sorting="handleV2Sort"
        @update:pagination="handleV2Pagination"
        @column-reorder="handleV2ColumnReorder"
        @row-click="handleV2RowClick"
        @row-action="handleV2RowAction"
      >
        <!-- Status Column -->
        <template #body-cell-status="{ row }">
          <q-badge
            v-if="row.status"
            transparent
            align="middle"
            :color="statusColor(row.status)"
          >
            {{ row.status }}
          </q-badge>
          <span v-else>-</span>
        </template>

        <!-- Paid Status Column -->
        <template #body-cell-paid_status="{ row }">
          <q-badge
            transparent
            align="middle"
            :color="statusColor(row.paid_status ?? 'Open')"
          >
            {{ row.paid_status ? row.paid_status : 'Open' }}
          </q-badge>
        </template>

        <!-- Payment Method Column -->
        <template #body-cell-payment_method="{ row }">
          {{ showPaymentMethodLabel(row.payment_method) || '-' }}
        </template>

        <!-- Electronic Payment Number Column -->
        <template #body-cell-electronic_payment_number="{ row }">
          {{ displayLastSixDigits(row.electronic_payment_number) || '-' }}
        </template>

        <!-- Extended Amount Column -->
        <template #body-cell-extended_amount="{ row }">
          <div align="right" style="padding-right: 16px">
            {{ row.extended_amount || '-' }}
          </div>
        </template>

        <!-- Invoice Date Column -->
        <template #body-cell-invoice_date="{ row }">
          {{ row.invoice_date ? formatDateTimeZone(row.invoice_date, true) : '-' }}
        </template>

        <!-- Invoice Due Date Column -->
        <template #body-cell-invoice_due_date="{ row }">
          {{ row.invoice_due_date ? formatDateTimeZone(row.invoice_due_date, true) : '-' }}
        </template>

        <!-- Payment Date Column -->
        <template #body-cell-payment_date="{ row }">
          {{ row.payment_date ? formatDateTimeZone(row.payment_date, true) : '-' }}
        </template>
      </DocBitsTable>
    </div>
  </div>

  <q-inner-loading :showing="loading" style="z-index: 2;">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { computed, defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import dragDropColumn from 'src/mixins/dragDropColumn';
import MessageBanner from 'src/components/MessageBanner.vue';
import generateSavedColumns from 'src/utils/generateSavedColumns';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { invoiceDashboardStore, useSettingStore } from 'src/store/main';
import InvoiceDashboardHelper from 'src/pages/Invoice/page/InvoiceDashboardHelper';
import InvoiceDashboardHeader from 'src/pages/Invoice/components/InvoiceHeader.vue';
import { invoice_dashboard_setting } from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { DocBitsTable } from 'src/components/Table';
import { getSavedPaginationSize } from 'src/components/Table/PaginationSettings.vue';
import type {
  RowActionItem,
  SortEventPayload,
  PaginationChangePayload,
  RowActionPayload,
  RowClickPayload,
  UnifiedTableColumn,
} from 'src/components/Table';
import { paymentMtdAPOptions } from 'src/supplier/constant';
import { getStatusColor } from 'src/pages/PurchaseOrders/constants.js';

export default defineComponent({
  mixins: [dragDropColumn, generateSavedColumns, dateUtils, InvoiceDashboardHelper],
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: 'invoice',
    },
  },
  components: {
    SubHeader,
    MessageBanner,
    InvoiceDashboardHeader,
    DocBitsTable,
  },
  data() {
    return {
      pagination_settings_key: 'INVOICE_PAGINATION_SIZE',
      show_table_loader: false,
      invoice_dashboard_setting,
    };
  },
  setup() {
    const invoice_store = invoiceDashboardStore();
    const { display_data, table_columns, loading, pagination, order_by } = storeToRefs(invoice_store);
    const { getInvoiceData, getSavedColumns, saveColumnOrder } = invoice_store;
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const tableColumns = ref(
      Object.values(table_columns.value)
        .map((column: any) => ({
          name: column.name,
          label: column.translation_key,
          field: column.field,
          actions: column.actions,
          order: column.order,
          required: true,
        }))
        .sort((a, b) => a.order - b.order),
    );

    // Raw pref may arrive as the string "0"/"false" (truthy in JS) — normalize
    // so the "dashboard disabled" banner matches the backend (DRFS-626).
    const invoiceDashboardDisabled = computed(
      () => !toBoolPreference(user_settings.value[invoice_dashboard_setting]),
    );

    return {
      invoice_store,
      table_columns,
      display_data,
      loading,
      pagination,
      order_by,
      tableColumns,
      user_settings,
      invoiceDashboardDisabled,
      visible_columns: ref({}) as dynamicObj,
      getInvoiceData,
      getSavedColumns,
      saveColumnOrder,
    };
  },
  computed: {
    /**
     * Table rows from store display_data
     */
    tableRows(): dynamicObj[] {
      return Array.isArray(this.display_data) ? this.display_data : Object.values(this.display_data);
    },

    /**
     * V2 Table: Transform table_columns to UnifiedTableColumn format
     */
    v2TableColumns(): UnifiedTableColumn[] {
      const visibleCols = this.visible_columns && Object.keys(this.visible_columns).length > 0
        ? this.visible_columns
        : this.table_columns;

      return Object.values(visibleCols)
        .map((column: any) => {
          const col: any = {
            name: column.name,
            label: this.$t(column.translation_key || column.label || column.name),
            field: column.name,
            sortable: column.actions === true,
            align: column.name === 'extended_amount' ? 'right' as const : 'left' as const,
            order: column.order,
          };

          // Make supplier_name column wider
          if (column.name === 'supplier_name') {
            col.style = 'min-width: 250px';
            col.headerStyle = 'min-width: 250px';
          }

          return col;
        })
        .sort((a: any, b: any) => a.order - b.order);
    },

    /**
     * V2 Table: Column order for persisted column reordering
     */
    v2ColumnOrder(): string[] {
      const visibleCols = this.visible_columns && Object.keys(this.visible_columns).length > 0
        ? this.visible_columns
        : this.table_columns;

      return Object.values(visibleCols)
        .sort((a: any, b: any) => a.order - b.order)
        .map((col: any) => col.name);
    },

    /**
     * V2 Table: Feature configuration
     */
    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: true,
        columnReorder: true,
        stickyFirstColumn: true,
        stickyLastColumn: true,
      };
    },

    /**
     * V2 Table: Pagination state (includes sort info)
     */
    v2PaginationState() {
      return {
        sortBy: this.order_by?.field_name || null,
        descending: this.order_by?.direction === 'desc',
        page: this.pagination.current_page,
        rowsPerPage: this.pagination.page_size,
        rowsNumber: this.pagination.total_pages * this.pagination.page_size,
      };
    },

    /**
     * V2 Table: Row actions configuration
     */
    v2RowActions(): RowActionItem[] {
      return [
        { key: 'view', label: 'view', icon: 'visibility', color: 'primary' },
      ];
    },
  },
  async mounted() {
    this.pagination.page_size = await getSavedPaginationSize(this.pagination_settings_key);
    await this.init();
    this.initDragDropColumns('invoice_table', 'label');
    document.addEventListener('invoice_table-column-drop', this.onDropColumns);
    this.visible_columns = await this.getSavedColumns();
    this.prepareTableColumns();
    document.addEventListener('columnsUpdated', this.handleColumnsUpdated);
  },
  unmounted() {
    document.removeEventListener('columnsUpdated', this.handleColumnsUpdated);
    document.removeEventListener(
      'invoice_table-column-drop',
      this.onDropColumns,
    );
  },
  methods: {
    // ========== V2 Table Event Handlers ==========
    async handleV2Sort(payload: SortEventPayload) {
      // Update store params for API call
      this.invoice_store.params.sort_by = payload.column;
      this.invoice_store.params.sort_order = payload.direction;

      // Also update order_by for consistency
      this.invoice_store.order_by = {
        field_name: payload.column,
        direction: payload.direction,
      };

      // Fetch data with new sort
      await this.getInvoices(true);
    },

    async handleV2Pagination(payload: PaginationChangePayload) {
      this.pagination.current_page = payload.page;
      this.pagination.page_size = payload.rowsPerPage;

      // Fetch data with new pagination
      await this.getInvoices(true);
    },

    handleV2RowClick(payload: RowClickPayload) {
      this.goToDetails(payload.row);
    },

    async handleV2ColumnReorder(columnNames: string[]) {
      // Map column names to column objects for the save API
      const columnsToSave = columnNames.map((name, index) => {
        const col = Object.values(this.table_columns).find((c: any) => c.name === name) as any;
        if (col) {
          return {
            ...col,
            order: index,
          };
        }
        return null;
      }).filter(Boolean);

      // Update local state
      this.tableColumns = columnsToSave;
      this.visible_columns = columnsToSave.reduce((acc: any, col: any, idx: number) => {
        acc[idx] = col;
        return acc;
      }, {});

      // Save to backend
      await this.savedOrderColumns(columnsToSave);
    },

    handleV2RowAction(payload: RowActionPayload) {
      if (payload.action === 'view') {
        this.goToDetails(payload.row);
      }
    },

    handleColumnsUpdated(e: any) {
      if (e.detail?.visible_columns) {
        this.visible_columns = e.detail.visible_columns;
        this.prepareTableColumns();
      }
    },
    // ========== End V2 Table Event Handlers ==========

    async init() {
      await this.getInvoices(true);
    },

    prepareTableColumns() {
      if (this.visible_columns && Object.keys(this.visible_columns).length > 0) {
        const cols = Object.values(this.visible_columns)
          .map((col: any) => ({
            name: col.name,
            label: col.translation_key,
            field: col.field,
            actions: col.actions,
            order: col.order,
            required: true,
          }))
          .sort((a: any, b: any) => a.order - b.order);
        this.tableColumns = cols;
      }
    },

    onDropColumns() {
      this.savedOrderColumns(this.tableColumns);
    },

    async savedOrderColumns(columns: any) {
      try {
        this.loading = true;
        await this.saveColumnOrder(columns);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async getInvoices(show_table_loader: boolean) {
      try {
        this.loading = true;
        if (show_table_loader) {
          this.show_table_loader = true;
        }

        await this.getInvoiceData();
      } catch (err: any) {
        logError(err);
      } finally {
        this.loading = false;
        this.show_table_loader = false;
      }
    },

    async paginationItemClicked() {
      try {
        await this.getInvoices(true);
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },

    // Navigation
    goToDetails(row: any) {
      const id = row?.id as string;
      this.$router.push(`/invoice/details/${id}`);
    },

    // Status color
    statusColor(status: string) {
      if (status) {
        return getStatusColor(status.toLowerCase()) || 'primary';
      }
      return '';
    },

    // Payment method label
    showPaymentMethodLabel(value: string) {
      const payment = paymentMtdAPOptions.find(
        (option) => option.value === value,
      ) as any;
      return payment ? payment.label : '';
    },

    // Display last six digits
    displayLastSixDigits(character: string) {
      if (character && character.length > 6) {
        return character.slice(-6);
      }
      return character;
    },

    // Set row style for exported rows
    setRowStyle(row: any) {
      if (
        row.hasOwnProperty('export_data_fetched') &&
        row['export_data_fetched'] === true
      ) {
        return 'exported-row';
      }
      return '';
    },
  },
});
</script>

<style scoped lang="scss">
body.body--light .dashboard-table-style .q-table td {
  background-color: #f7f7f7 !important;
}

body.body--dark .dashboard-table-style .q-table td {
  background-color: #383838 !important;
}
</style>
